const stopAllExpiredLifeExperimentRounds = `-- name: StopAllExpiredLifeExperimentRounds :many
UPDATE life_experiment_round
SET status = 'awaiting_review',
    stopped_at = COALESCE(stopped_at, ends_at, now()),
    stop_reason = CASE WHEN btrim(stop_reason) = '' THEN 'expired' ELSE stop_reason END,
    updated_at = now()
WHERE status = 'running' AND ends_at <= now()
RETURNING id, experiment_id, previous_round_id, proposal_id, issue_id, status, plan, starts_at, ends_at, stopped_at, stop_reason, confirmed_at, confirmed_by_id, review, reviewed_at, created_at, updated_at, review_draft
`

func (q *Queries) StopAllExpiredLifeExperimentRounds(ctx context.Context) ([]LifeExperimentRound, error) {
	rows, err := q.db.Query(ctx, stopAllExpiredLifeExperimentRounds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LifeExperimentRound{}
	for rows.Next() {
		var i LifeExperimentRound
		if err := rows.Scan(
			&i.ID,
			&i.ExperimentID,
			&i.PreviousRoundID,
			&i.ProposalID,
			&i.IssueID,
			&i.Status,
			&i.Plan,
			&i.StartsAt,
			&i.EndsAt,
			&i.StoppedAt,
			&i.StopReason,
			&i.ConfirmedAt,
			&i.ConfirmedByID,
			&i.Review,
			&i.ReviewedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ReviewDraft,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

